import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    url_pattern = r'https?://[^\s<>"{}|\\^`\[\]]+'
    urls = re.findall(url_pattern, myString)

    domains = set()
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        if parsed.netloc:
            domains.add(parsed.netloc)

    result = {}
    api_base = "http://ip-api.com/json/"

    for domain in domains:
        try:
            response = requests.get(f"{api_base}{domain}?key={API_KEY}")
            if response.status_code == 200:
                result[domain] = response.json()
            else:
                result[domain] = None
        except Exception:
            result[domain] = None

    return result

