import json
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd
def task_func(json_data: str, key_path: list):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON string")

    current = data
    for key in key_path:
        if isinstance(current, dict) and key in current:
            current = current[key]
        else:
            raise KeyError(f"Key '{key}' not found")

    if not isinstance(current, list) or len(current) == 0:
        raise ValueError("No numeric data found or data is empty")

    numeric_data = []
    for item in current:
        if isinstance(item, (int, float)):
            numeric_data.append(item)
        else:
            raise ValueError("Data contains non-numeric values")

    if len(numeric_data) == 0:
        raise ValueError("No numeric data found after filtering")

    df = pd.DataFrame({'values': numeric_data})
    fig, ax = plt.subplots()
    sns.boxplot(data=df, y='values', ax=ax)
    return fig
